276	    /**
277	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
278	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
279	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
280	     * empty string.
281	     *
282	     * @param value the raw value (last name or address) as submitted
283	     * @return the normalized comparison key
284	     */
285	    private String normalizeForHousehold(String value) {
286	        if (value == null) {
287	            return "";
288	        }
289	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
