292	    /**
293	     * Derives the stable shared household identifier for a household, keyed on the normalized last
294	     * name and address. Because it is a pure function of those normalized keys, every owner in the
295	     * same household deterministically computes the same value. The identifier is the first 12
296	     * upper-case hex characters of the SHA-256 digest of the two keys joined with a NUL separator
297	     * (the separator prevents distinct name/address pairs from colliding).
298	     *
299	     * @param lastNameKey the normalized last-name comparison key
300	     * @param addressKey  the normalized address comparison key
301	     * @return the stable household identifier
302	     */
303	    private String householdId(String lastNameKey, String addressKey) {
304	        String seed = lastNameKey + "�" + addressKey;
305	        try {
306	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
307	                .digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
308	            StringBuilder sb = new StringBuilder(digest.length * 2);
309	            for (byte b : digest) {
310	                sb.append(String.format("%02x", b));
311	            }
312	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
313	        }
314	        catch (java.security.NoSuchAlgorithmException e) {
