319	    /**
320	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
321	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
322	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
323	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
324	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
325	     * is stored as {@code '+61412345678'}.
326	     *
327	     * @param telephone the raw telephone number as submitted
328	     * @return the normalized E.164 telephone number
329	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
330	     *         number (8 to 15 digits after the '+')
331	     */
332	    private String normalizeTelephone(String telephone) {
333	        String raw = telephone == null ? "" : telephone.trim();
334	        String digits = raw.replaceAll("\\D", "");
335	        String e164;
336	        if (raw.startsWith("+")) {
337	            e164 = "+" + digits;
338	        } else {
339	            if (digits.startsWith("0")) {
340	                digits = digits.substring(1);
341	            }
342	            e164 = "+61" + digits;
343	        }
344	        int digitCount = e164.length() - 1;
345	        if (digitCount < 8 || digitCount > 15) {
346	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
347	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
348	        }
349	        return e164;
350	    }
351	
352	    /**
353	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
354	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
355	     * (absent) or already valid.
356	     *
357	     * @param email the email address as submitted, or {@code null} when absent
358	     * @return the lower-cased email, or {@code null} when absent
359	     */
360	    private String normalizeEmail(String email) {
361	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
362	    }
